ALTER TABLE "Balance" ADD CONSTRAINT "balance_quantities" CHECK ("onHand" >= 0 AND reserved >= 0 AND reserved <= "onHand");
ALTER TABLE "Request" ADD CONSTRAINT "request_quantity" CHECK (requested >= 0);
ALTER TABLE "AllocationLine" ADD CONSTRAINT "line_quantity" CHECK (quantity > 0);
ALTER TABLE "Membership" ADD CONSTRAINT "membership_role" CHECK ((role = 'COORDINATOR' AND "centerId" IS NULL) OR (role = 'CENTER' AND "centerId" IS NOT NULL));
ALTER TABLE "AllocationLine" ADD CONSTRAINT "line_status" CHECK (status IN ('RESERVED', 'DELIVERED', 'CANCELLED'));
ALTER TABLE "AllocationRun" ADD CONSTRAINT "run_status" CHECK (status IN ('DRAFT', 'CONFIRMED'));
ALTER TABLE "Center" ADD CONSTRAINT "center_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
ALTER TABLE "Center" ADD CONSTRAINT "center_org_unique" UNIQUE (id, "organizationId");
ALTER TABLE "Product" ADD CONSTRAINT "product_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
ALTER TABLE "Product" ADD CONSTRAINT "product_org_unique" UNIQUE (id, "organizationId");
ALTER TABLE "Campaign" ADD CONSTRAINT "campaign_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
ALTER TABLE "Campaign" ADD CONSTRAINT "campaign_org_unique" UNIQUE (id, "organizationId");
ALTER TABLE "Membership" ADD CONSTRAINT "membership_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
ALTER TABLE "Membership" ADD CONSTRAINT "membership_center_fk" FOREIGN KEY ("centerId", "organizationId") REFERENCES "Center"(id, "organizationId");
ALTER TABLE "Request" ADD CONSTRAINT "request_center_org_fk" FOREIGN KEY ("centerId", "organizationId") REFERENCES "Center"(id, "organizationId");
ALTER TABLE "Request" ADD CONSTRAINT "request_product_org_fk" FOREIGN KEY ("productId", "organizationId") REFERENCES "Product"(id, "organizationId");
ALTER TABLE "Request" ADD CONSTRAINT "request_campaign_org_fk" FOREIGN KEY ("campaignId", "organizationId") REFERENCES "Campaign"(id, "organizationId");
ALTER TABLE "Balance" ADD CONSTRAINT "balance_product_org_fk" FOREIGN KEY ("productId", "organizationId") REFERENCES "Product"(id, "organizationId");
ALTER TABLE "Event" ADD CONSTRAINT "event_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
ALTER TABLE "AllocationRun" ADD CONSTRAINT "run_org_fk" FOREIGN KEY ("organizationId") REFERENCES "Organization"(id);
